// New classroom catalogue: mechanics, mode ownership, subject suitability and editable grade banks.
const EXPANSION={
 mars:{name:'Race to Mars',mode:'TEAM',emoji:'🚀',subjects:['math'],rule:'Engineer, Navigator and Captain agree whether to cruise, boost or repair. Correct answers replenish fuel and oxygen. First ship to reach 8 distance wins.'},
 island:{name:'Survival Island',mode:'TEAM',emoji:'🏝️',subjects:['english'],rule:'Agree how to spend supplies on food, water, shelters or rescue signals. Storms and shortages affect your settlement. Only surviving teams rank. Rescue score: 5 per signal, 2 per shelter, plus remaining food and water.'},
 territory:{name:'Territory Wars',mode:'TEAM',emoji:'🗺️',subjects:['english','math'],rule:'Earn action points and capture adjacent territories on a 24-cell map. Gold-star territories earn extra action points. Keep playing until time expires; highest territory count wins.'},
 raid:{name:'Boss Raid',mode:'TEAM',emoji:'🐉',subjects:['english','math'],rule:'Assign attacker, healer and defender. Correct answers and streaks earn action points. Choose attacks, healing or shields. First team to defeat its boss wins.'},
 spy:{name:'Spy Network',mode:'TEAM',emoji:'🕵️',subjects:['english'],input:'secret',rule:'Pass the device privately to each team’s three agents. Each gets a different clue. Combine clues without reopening them; the first team to name the secret term wins. Three guesses per team.'},
 build:{name:'Build It!',mode:'TEAM',emoji:'🏗️',subjects:['math'],rule:'Earn materials through questions. A correct answer on every third round includes a rare component. Build a foundation, three tower levels and an antenna. First completed structure wins.'},
 tycoon:{name:'Classroom Tycoon',mode:'TEAM',emoji:'💰',subjects:['math'],rule:'Agree business investments: employees, factories or advertising. Correct answers earn cash; staff and factories generate income at changing market prices. Highest cash plus resale value wins.'},
 fleet:{name:'Treasure Fleet',mode:'TEAM',emoji:'🏴‍☠️',subjects:['english','math'],rule:'Choose a safe coast, valuable reef, dangerous storm route or repairs. Correct answers earn sailing fuel. Balance treasure against ship damage. Highest treasure on an afloat ship wins.'},
 crystal:{name:'Capture the Crystal',mode:'TEAM',emoji:'💎',subjects:['english','math'],rule:'Earn action points and agree whether to shield, scout, set a trap or attack a rival crystal. Defenses resolve before attacks. Capture the most crystals by the last round; remaining shields break ties.'},
 monster:{name:'Defeat the Monster',mode:'CLASS',emoji:'👾',subjects:['english','math'],rule:'One monster, one class. Agree answers to deal damage. The monster retaliates on mistakes and becomes more dangerous in its final phase. Defeat it before the class loses all hearts.'},
 mission:{name:'Class Mission Control',mode:'CLASS',emoji:'🛰️',subjects:['math'],rule:'The class runs one spacecraft. Questions earn fuel and oxygen. Vote to explore, head home or repair shields. Reach home before oxygen or hull runs out.'},
 escape:{name:'The Classroom Escape Room',mode:'CLASS',emoji:'🔐',subjects:['english','math'],rule:'Solve two questions per lock to reveal each digit of the exit code. Wrong answers cost 30 seconds. Enter the three-digit code before active-play time expires.'},
 poll:{name:'Guess What the Class Thinks',mode:'CLASS',emoji:'🧠',subjects:['english'],rule:'Pass one device for anonymous choices. No names are collected and results stay hidden until voting closes. Reveal the graph, discuss different viewpoints, then advance together.'},
 disaster:{name:'Disaster!',mode:'CLASS',emoji:'🌋',subjects:['english'],rule:'The class manages one city. Questions earn supplies. Vote to evacuate, reinforce shelters or restore communications as hazards intensify. Your choices change safety and the unfolding story.'},
 streak:{name:'Class Streak',mode:'CLASS',emoji:'🎯',subjects:['english','math'],rule:'Reach three times the question-pool size in correct class decisions before three mistakes. Questions reshuffle for revision. Build an unbroken streak and celebrate milestones together.'},
 impostor:{name:'Who Is the Impostor?',mode:'CLASS',emoji:'🎭',subjects:['english'],input:'secret',rule:'Pass the device privately to each numbered student. Most see the secret term; one or two see only its category. Ask each other questions, discuss, then make a class accusation.'},
 higher:{name:'Higher or Lower',mode:'CLASS',emoji:'📈',subjects:['math'],input:'number',rule:'Compare the next value with the revealed reference. The class votes Higher, Lower or Equal. Reveal and explain the comparison, then try to grow your shared streak.'},
 adventure:{name:'Classroom Adventure',mode:'CLASS',emoji:'🧭',subjects:['english'],rule:'The class guides one explorer through an ancient temple. Questions earn keys; votes choose doors, towers or tunnels. Routes change artifacts, maps and hearts. Collect four artifacts and survive.'}
};
FORMATS.kingdom.name='Kingdom Clash';FORMATS.kingdom.instructions+=' Build defenses to prevent a gold loss every third round, or recruit an army for two prestige.';FORMATS.earth.name='Save the World';
for(const g of GAMES){if(g.format==='kingdom')g.title=g.title.replace('Kingdom Builders','Kingdom Clash');if(g.format==='earth')g.title=g.title.replace('Save Our Earth','Save the World');}
for(const [id,c] of Object.entries(EXPANSION)){
 FORMATS[id]={name:c.name,mode:c.mode,icon:c.emoji,input:c.input||'choice',description:c.rule.split('. ')[0]+'.',instructions:c.rule};
 for(const subject of c.subjects)for(const grade of [7,8]){
  const source=GAMES.find(g=>g.id===`${subject}-${grade}-${c.input==='secret'?'clue':'quiz'}`),g=JSON.parse(JSON.stringify(source));g.id=`${subject}-${grade}-${id}`;g.format=id;g.title=`${c.name}: ${g.topic}`;g.minutes=['escape','territory'].includes(id)?'10–20':'15–25';
  if(id==='higher'){g.topic=grade===7?'Comparing signed numbers':'Powers, roots and decimals';const rows=grade===7?[['−8 + 13',5],['6 − (−4)',10],['−7 × 3',-21],['−24 ÷ (−6)',4],['−3 + (−9)',-12],['5 − 2 × 4',-3]]:[['2⁵',32],['√144',12],['3² × 3³',243],['5⁰',1],['2⁻³',0.125],['√0.81',0.9]];g.items=rows.map(([prompt,n])=>({prompt,answer:String(n),options:[],hint:'',explanation:''}));g.title=`${c.name}: ${g.topic}`;}
  if(id==='poll'){g.topic=grade===7?'Reading preferences and interpretations':'Evaluating persuasive choices';const rows=grade===7?[['What makes a story most memorable?','Characters','Setting','Plot twists'],['Which clue helps you infer a character’s feelings?','Dialogue','Actions','Description'],['What makes an unfamiliar word easier to understand?','Context','Word parts','An example'],['Which opening makes you want to read on?','A mystery','An action scene','A vivid place']]:[['Which kind of support persuades you most?','Reliable data','A personal story','Expert reasoning'],['What makes a counterargument effective?','Fairness','Evidence','Clear rebuttal'],['Which technique is easiest to overuse?','Rhetorical questions','Repetition','Emotional language'],['What should a conclusion do first?','Restate the claim','Connect the evidence','Invite action']];g.items=rows.map(([prompt,answer,...options])=>({prompt,answer,options,hint:'',explanation:'There can be several defensible viewpoints. Ask students to justify their choices.'}));g.title=`${c.name}: ${g.topic}`;}
  GAMES.push(g);
 }
}
